def compute(vars):
    loans_pledged = vars["v1"]
    total_assets_pledged = vars["v2"]

    if total_assets_pledged == 0:
        return {
            "value": None,
            "trace": {
                "loans_pledged": loans_pledged,
                "total_assets_pledged": total_assets_pledged,
                "output_meta": {
                    "currency": None,
                    "scale": None,
                    "unit": "percentage"
                }
            }
        }

    percentage = loans_pledged / total_assets_pledged * 100

    return {
        "value": percentage,
        "trace": {
            "loans_pledged": loans_pledged,
            "total_assets_pledged": total_assets_pledged,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
